// Convert input points to CGAL points
std::list<Site_2> sites;
for (const cg3::Point2d& p : sites_input) {
    sites.push_back(Site_2::make_point(p.x(), p.y()));
}

// Construct the Voronoi diagram
VD vd(sites.begin(), sites.end());

// Prepare result container
std::vector<std::vector<cg3::Point2d>> result;

// Iterate over all faces of the Voronoi diagram
for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    std::vector<cg3::Point2d> cell;

    // Get the halfedge on the boundary of the face
    VD::Ccb_halfedge_circulator circ = fit->ccb();

    // Traverse the boundary and collect vertices
    do {
        if (!circ->has_target()) {
            circ++;
            continue;
        }
        const Point_2& p = circ->target()->point();
        cell.push_back(cg3::Point2d(CGAL::to_double(p.x()), CGAL::to_double(p.y())));
        circ++;
    } while (circ != fit->ccb());

    result.push_back(cell);
}

return result;

